{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE qcom_distance as ( WITH base AS ( SELECT op.channel_order_number AS order_no, op.created_at AS created_ist, CASE WHEN DATE_PART(\'HOUR\', op.created_at) >= 22 THEN DATEADD( \'HOUR\', 10, TO_TIMESTAMP_NTZ(DATEADD(\'DAY\', 1, TO_DATE(op.created_at))) ) WHEN DATE_PART(\'HOUR\', op.created_at) < 10 THEN DATEADD( \'HOUR\', 10, TO_TIMESTAMP_NTZ(TO_DATE(op.created_at)) ) ELSE op.created_at END AS created_frozen_ist, op.DELIVERY_DATE AS delivered_ist, TRY_TO_DOUBLE(NULLIF(op.DROP_LAT, \'\')) AS DROP_LAT, TRY_TO_DOUBLE(NULLIF(op.DROP_LON, \'\')) AS DROP_LON, TRY_TO_DOUBLE(NULLIF(op.PICKUP_LAT, \'\')) AS PICKUP_LAT, TRY_TO_DOUBLE(NULLIF(op.PICKUP_LON, \'\')) AS PICKUP_LON FROM omni_order_processing_meta op WHERE op.is_quick_com = TRUE AND op.DELIVERY_DATE IS NOT NULL ), per_order AS ( SELECT order_no, TO_DATE(created_frozen_ist) AS business_day, 6371.0 * 2 * ASIN( SQRT( POWER(SIN(RADIANS((DROP_LAT - PICKUP_LAT)) / 2), 2) + COS(RADIANS(PICKUP_LAT)) * COS(RADIANS(DROP_LAT)) * POWER(SIN(RADIANS((DROP_LON - PICKUP_LON)) / 2), 2) ) ) AS distance_km, DATEDIFF(\'SECOND\', created_frozen_ist, delivered_ist) / 60.0 AS o2d_minutes FROM base ), bucketted AS ( SELECT business_day, CASE WHEN distance_km < 5 THEN \'<5 km\' WHEN distance_km <= 10 THEN \'5–10 km\' WHEN distance_km > 10 THEN \'>10 km\' ELSE NULL END AS distance_bucket, CASE WHEN distance_km < 5 THEN 1 WHEN distance_km <= 10 THEN 2 WHEN distance_km > 10 THEN 3 ELSE 4 END AS bucket_order, order_no, o2d_minutes, CASE WHEN distance_km <= 3 THEN 52 ELSE 52 + ((distance_km - 3) * 10) END AS delivery_cost FROM per_order ), day_totals AS ( SELECT business_day, COUNT(DISTINCT order_no) AS total_orders_day FROM bucketted GROUP BY business_day ) SELECT b.business_day, b.distance_bucket, dt.total_orders_day, COUNT(DISTINCT b.order_no) AS orders, ROUND(AVG(b.o2d_minutes), 1) AS avg_o2d_mins, ROUND(AVG(b.delivery_cost), 1) AS avg_delivery_cost, ROUND( (COUNT(DISTINCT CASE WHEN b.o2d_minutes <= 60 THEN b.order_no END) * 1.0) / NULLIF(COUNT(DISTINCT b.order_no), 0), 3 ) AS under_60, ROUND( (COUNT(DISTINCT CASE WHEN b.o2d_minutes <= 75 THEN b.order_no END) * 1.0) / NULLIF(COUNT(DISTINCT b.order_no), 0), 3 ) AS under_75 FROM bucketted b JOIN day_totals dt ON dt.business_day = b.business_day GROUP BY b.business_day, b.distance_bucket, b.bucket_order, dt.total_orders_day ORDER BY b.business_day, b.bucket_order ); CREATE OR REPLACE TABLE qcom_blr_funnel as ( WITH base_payment AS ( SELECT ORDER_NAME, pincode, ORDER_TIMESTAMP, sku FROM fact_items_snitch WHERE ORDER_TIMESTAMP >= DATEADD(day, -120, CURRENT_TIMESTAMP()) AND ORDER_TIMESTAMP < DATEADD(day, 1, CURRENT_TIMESTAMP()) AND ORDER_NAME IS NOT NULL AND (pincode ILIKE \'560%\' OR pincode IS NULL) ), order_qcom_flag AS ( SELECT channel_order_number, BOOLOR_AGG(COALESCE(is_quick_com, FALSE)) AS is_quick_com FROM omni_order_processing_meta GROUP BY channel_order_number ), order_totals AS ( SELECT channel_order_number, MAX(cod_charge) AS order_shipping FROM omni_order_processing_meta GROUP BY channel_order_number ), eligible_pincodes_hsr AS ( SELECT DISTINCT shipping_pincode FROM omni_order_processing_meta WHERE branch_code = \'13\' AND is_quick_com = TRUE AND created_at > DATEADD(day, -10, CURRENT_DATE()) ), eligible_skus_hsr AS ( SELECT inventory_logs, sku FROM omni_inventory_meta_hourly WHERE quick_com_available = TRUE AND branch_code = \'13\' AND inventory_total > 0 GROUP BY 1,2 ), eligible_pincodes_kly AS ( SELECT DISTINCT shipping_pincode FROM omni_order_processing_meta WHERE branch_code = \'52\' AND is_quick_com = TRUE AND created_at > DATEADD(day, -10, CURRENT_DATE()) ), eligible_skus_kly AS ( SELECT inventory_logs, sku FROM omni_inventory_meta_hourly WHERE quick_com_available = TRUE AND branch_code = \'52\' AND inventory_total > 0 GROUP BY 1,2 ), eligible_matrix AS ( SELECT \'13\' AS branch_code, ep.shipping_pincode AS pincode, es.sku, inventory_logs, FROM eligible_pincodes_hsr ep CROSS JOIN eligible_skus_hsr es UNION ALL SELECT \'52\', ep.shipping_pincode, es.sku, inventory_logs FROM eligible_pincodes_kly ep CROSS JOIN eligible_skus_kly es ), joined AS ( SELECT CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP) AS dt_ist, CASE WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP)) >= 22 THEN DATEADD( hour, 9, DATEADD( day, 1, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP)) ) ) WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP)) < 10 THEN DATEADD( hour, 9, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP)) ) ELSE CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP) END AS created_frozen_ist, p.ORDER_NAME, NULLIF(p.sku, \'\') AS sku, NULLIF(p.pincode, \'\') AS pincode, COALESCE(oq.is_quick_com, FALSE) AS is_quick_com, (NULLIF(p.pincode, \'\') IN (SELECT DISTINCT pincode FROM eligible_matrix)) AS is_qcom_eligible_pincode, (em.sku IS NOT NULL AND is_qcom_eligible_pincode) AS is_qcom_eligible FROM base_payment p LEFT JOIN order_qcom_flag oq ON oq.channel_order_number = p.ORDER_NAME LEFT JOIN ( SELECT DISTINCT inventory_logs::date, pincode, sku, inventory_logs, FROM eligible_matrix ) em ON em.sku = NULLIF(p.sku, \'\') AND em.pincode = NULLIF(p.pincode, \'\') AND em.inventory_logs::DATE = p.ORDER_TIMESTAMP::DATE AND em.inventory_logs <= p.ORDER_TIMESTAMP WHERE NULLIF(p.pincode, \'\') ILIKE \'560%\' ), filter AS ( SELECT j.*, TO_DATE(created_frozen_ist) AS business_date FROM joined j WHERE TO_DATE(created_frozen_ist) BETWEEN DATEADD( day, -120, TO_DATE(CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', CURRENT_TIMESTAMP())) ) AND TO_DATE(CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', CURRENT_TIMESTAMP())) ), pi_sku AS ( SELECT sku, MAX(shopify_product_id) AS shopify_product_id FROM omni_inventory_meta GROUP BY sku ) SELECT f.business_date, f.ORDER_NAME, f.sku, pi.shopify_product_id, f.pincode, f.is_quick_com, f.is_qcom_eligible_pincode, f.is_qcom_eligible, f.dt_ist, f.created_frozen_ist FROM filter f LEFT JOIN pi_sku pi ON pi.sku = f.sku ORDER BY f.business_date, f.ORDER_NAME, f.sku ); CREATE OR REPLACE TABLE qcom_weekly AS ( WITH joined_orders AS ( SELECT op.STORE_NAME, op.channel_order_number, op.created_at AS created_ist, op.PICK_LIST_COMPLETED AS picked_ist, op.packed_at AS packed_ist, op.manifested_at AS manifested_ist, CASE WHEN DATE_PART(\'HOUR\', op.created_at) >= 22 THEN DATEADD( \'HOUR\', 9, TO_TIMESTAMP_NTZ(DATEADD(\'DAY\', 1, TO_DATE(op.created_at))) ) WHEN DATE_PART(\'HOUR\', op.created_at) < 9 THEN DATEADD( \'HOUR\', 9, TO_TIMESTAMP_NTZ(TO_DATE(op.created_at)) ) ELSE op.created_at END AS created_frozen_ist_m, CASE WHEN DATE_PART(\'HOUR\', op.created_at) >= 22 THEN DATEADD( \'HOUR\', 10, TO_TIMESTAMP_NTZ(DATEADD(\'DAY\', 1, TO_DATE(op.created_at))) ) WHEN DATE_PART(\'HOUR\', op.created_at) < 10 THEN DATEADD( \'HOUR\', 10, TO_TIMESTAMP_NTZ(TO_DATE(op.created_at)) ) ELSE op.created_at END AS created_frozen_ist_d, op.HANDOVER_DATE AS picked_up_ist, op.OUTFORDELIVERY_DATE AS out_for_delivery_ist, op.DELIVERY_DATE AS delivered_ist, op.RTO_MARK_DATE AS rto_ist, op.order_status, op.cancelled_by, op.STORE_NAME FROM omni_order_processing_meta op WHERE op.is_quick_com = TRUE ), metrics AS ( SELECT TO_CHAR(DATE_TRUNC(\'WEEK\', created_ist), \'YYYY-MM-DD\') AS week, COUNT(DISTINCT channel_order_number) AS total_orders, COUNT(*) AS total_items, COUNT(manifested_ist) AS processed_items, COUNT(delivered_ist) AS delivered_items, COUNT(DISTINCT CASE WHEN delivered_ist IS NOT NULL THEN channel_order_number END) AS delivered_orders, GREATEST( COUNT(CASE WHEN order_status NOT IN (\'CANCELLED\',\'AWB_FAILED\',\'NOT_FOUND\') THEN 1 END) - COUNT(manifested_ist), 0 ) AS pending_items, SUM(CASE WHEN order_status = \'CANCELLED\' THEN 1 ELSE 0 END) AS cancelled_items, SUM(CASE WHEN rto_ist IS NOT NULL THEN 1 ELSE 0 END) AS rto_items, SUM(CASE WHEN order_status = \'AWB_FAILED\' THEN 1 ELSE 0 END) AS awb_errors, SUM(CASE WHEN order_status = \'NOT_FOUND\' THEN 1 ELSE 0 END) AS not_found, SUM(CASE WHEN order_status = \'CANCELLED\' AND cancelled_by IS NULL THEN 1 ELSE 0 END) AS customer_cancelled, ROUND(AVG(DATEDIFF(\'SECOND\', created_frozen_ist_m, manifested_ist) / 60.0))::INT AS o2m_mins, ROUND(AVG(DATEDIFF(\'SECOND\', created_frozen_ist_d, delivered_ist) / 60.0))::INT AS o2d_mins, ROUND(AVG(DATEDIFF(\'SECOND\', created_frozen_ist_m, picked_ist) / 60.0))::INT AS o2p_mins, ROUND(AVG(DATEDIFF(\'SECOND\', picked_ist, packed_ist) / 60.0))::INT AS p2p_mins, ROUND(AVG(DATEDIFF(\'SECOND\', packed_ist, manifested_ist)/ 60.0))::INT AS p2m_mins, ROUND(AVG(DATEDIFF(\'SECOND\', manifested_ist, picked_up_ist) / 60.0))::INT AS m2h_mins, ROUND(AVG(DATEDIFF(\'SECOND\', picked_up_ist, delivered_ist) / 60.0))::INT AS h2d_mins, PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY (DATEDIFF(\'SECOND\', created_frozen_ist_d, delivered_ist) / 60.0)) AS o2d_p90_mins, COUNT(manifested_ist) * 1.0 / NULLIF(COUNT(CASE WHEN NOT (order_status = \'CANCELLED\' AND cancelled_by IS NULL) THEN 1 END), 0) AS ff_percent, COUNT(CASE WHEN order_status IN (\'AWB_FAILED\',\'NOT_FOUND\') OR (order_status = \'CANCELLED\' AND cancelled_by IS NOT NULL) THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN NOT (order_status = \'CANCELLED\' AND cancelled_by IS NULL) THEN 1 END), 0) AS er_percent, COUNT(CASE WHEN manifested_ist IS NOT NULL AND (DATEDIFF(\'SECOND\', created_frozen_ist_m, manifested_ist) / 60.0) <= 5 THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN manifested_ist IS NOT NULL AND order_status NOT IN (\'CANCELLED\',\'AWB_FAILED\',\'NOT_FOUND\') THEN 1 END), 0) AS o2m_sla, COUNT(CASE WHEN delivered_ist IS NOT NULL AND (DATEDIFF(\'SECOND\', created_frozen_ist_d, delivered_ist) / 60.0) <= 60 THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN delivered_ist IS NOT NULL AND order_status NOT IN (\'CANCELLED\',\'AWB_FAILED\',\'NOT_FOUND\') THEN 1 END), 0) AS o2d_60_sla, COUNT(CASE WHEN delivered_ist IS NOT NULL AND (DATEDIFF(\'SECOND\', created_frozen_ist_d, delivered_ist) / 60.0) <= 120 THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN delivered_ist IS NOT NULL AND order_status NOT IN (\'CANCELLED\',\'AWB_FAILED\',\'NOT_FOUND\') THEN 1 END), 0) AS o2d_120_sla, COUNT(CASE WHEN delivered_ist IS NOT NULL AND (DATEDIFF(\'SECOND\', created_frozen_ist_d, delivered_ist) / 60.0) > 60 THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN delivered_ist IS NOT NULL AND order_status NOT IN (\'CANCELLED\',\'AWB_FAILED\',\'NOT_FOUND\') THEN 1 END), 0) AS out_tat_percent FROM joined_orders WHERE created_frozen_ist_d >= TO_TIMESTAMP_NTZ(\'2025-09-04\') GROUP BY 1 ) SELECT week, total_orders, total_items, processed_items, pending_items, delivered_items, delivered_orders, cancelled_items, rto_items, awb_errors, not_found, customer_cancelled, o2m_mins, o2d_mins, o2d_p90_mins, o2p_mins, p2p_mins, p2m_mins, m2h_mins, h2d_mins, ff_percent, er_percent, o2m_sla, o2d_60_sla, o2d_120_sla, out_tat_percent FROM metrics ORDER BY week DESC ); CREATE OR REPLACE TABLE qcom_orders_customer_state AS ( WITH snitchx_membership AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) AS snitchx_enrolled_at FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), phone_book AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone FROM snitch_db.maplemonk.snitchx_phone WHERE phone IS NOT NULL ), qcom_orders AS ( SELECT DISTINCT TO_VARCHAR(channel_order_number) AS order_id, RIGHT(REGEXP_REPLACE(customer_phone, \'[^0-9]\', \'\'), 10) AS phone FROM snitch_db.maplemonk.omni_order_processing_meta WHERE is_quick_com = TRUE AND channel_order_number IS NOT NULL ), qcom_users AS ( SELECT DISTINCT phone FROM qcom_orders WHERE phone IS NOT NULL AND phone <> \'\' ), qcom_pincodes AS ( SELECT DISTINCT TRY_TO_NUMBER(shipping_pincode) AS pincode FROM snitch_db.maplemonk.omni_order_processing_meta WHERE is_quick_com = TRUE AND TRY_TO_NUMBER(shipping_pincode) IS NOT NULL ), impact_users AS ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND TRY_TO_NUMBER(pincode) IN (SELECT pincode FROM qcom_pincodes) AND phone IS NOT NULL ), online_orders AS ( SELECT TO_CHAR(TO_NUMBER(REGEXP_REPLACE(order_name,\'[^0-9]\',\'\'))) AS order_id, RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone, TRIM(customer_id) AS shopify_user_id, \'Online\' AS channel, MIN(order_timestamp) AS order_ts, SUM(gross_sales)::NUMBER AS order_value, NULL AS store_code, pincode FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' GROUP BY 1,2,3,8 ), offline_orders AS ( SELECT bill_no AS order_id, RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) AS phone, COALESCE( NULLIF(TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')), \'\'), pb.shopify_user_id ) AS shopify_user_id, \'Offline\' AS channel, COALESCE( TRY_TO_TIMESTAMP(vouch_time), TRY_TO_TIMESTAMP(vouch_time, \'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time, \'MON DD, YYYY, HH12:MI AM\'), TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') ) AS order_ts, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9\.-]\',\'\'))) AS order_value, TRY_TO_NUMBER(store_code) AS store_code, NULL as pincode, FROM snitch_db.maplemonk.retail_order_summary ros LEFT JOIN phone_book pb ON pb.phone = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE COALESCE(ros.shopify_user_id, pb.shopify_user_id) IS NOT NULL AND branch_name NOT LIKE \'%SNITCH - WH%\' GROUP BY 1,2,3,5,7 ), order_base AS ( SELECT * FROM ( SELECT * FROM online_orders UNION ALL SELECT * FROM offline_orders ) WHERE phone IN (SELECT phone FROM impact_users) ), order_state AS ( SELECT o.*, IFF(qo.order_id IS NOT NULL, TRUE, FALSE) AS is_qcom, SUM(IFF(qo.order_id IS NOT NULL, 1, 0)) OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS qcom_orders_before, SUM(IFF(qo.order_id IS NOT NULL, 1, 0)) OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS qcom_orders_lifetime, MIN(IFF(qo.order_id IS NOT NULL, o.order_ts, NULL)) OVER ( PARTITION BY o.phone ) AS first_qcom_ts, COUNT(*) OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS orders_before, COUNT(*) OVER ( PARTITION BY o.phone ORDER BY o.order_ts RANGE BETWEEN INTERVAL \'12 MONTH\' PRECEDING AND INTERVAL \'1 SECOND\' PRECEDING ) AS orders_12m_before, COUNT_IF(o.channel = \'Online\') OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS online_orders_before, COUNT_IF(o.channel = \'Offline\') OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS offline_orders_before, DATEDIFF( \'day\', LAG(o.order_ts) OVER (PARTITION BY o.phone ORDER BY o.order_ts), o.order_ts ) AS days_since_last_order, COUNT(*) OVER ( PARTITION BY o.phone ORDER BY o.order_ts RANGE BETWEEN INTERVAL \'30 DAY\' PRECEDING AND INTERVAL \'1 SECOND\' PRECEDING ) AS orders_last_30d, COUNT(*) OVER ( PARTITION BY o.phone ORDER BY o.order_ts RANGE BETWEEN INTERVAL \'90 DAY\' PRECEDING AND INTERVAL \'1 SECOND\' PRECEDING ) AS orders_last_90d, sm.snitchx_enrolled_at, COUNT_IF(o.order_ts >= sm.snitchx_enrolled_at) OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS snitchx_orders_before, IFF(o.channel = \'Online\' AND online_orders_before = 0, TRUE, FALSE) AS is_first_online_order, IFF( IFF(qo.order_id IS NOT NULL, 1, 0) = SUM(IFF(qo.order_id IS NOT NULL, 1, 0)) OVER ( PARTITION BY o.phone ORDER BY o.order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ), IFF(qo.order_id IS NOT NULL, TRUE, FALSE), FALSE ) AS is_first_qcom_order FROM order_base o LEFT JOIN qcom_orders qo ON qo.order_id = TO_VARCHAR(o.order_id) LEFT JOIN snitchx_membership sm ON o.shopify_user_id = sm.shopify_user_id ) SELECT order_id, order_ts, channel, store_code, phone, shopify_user_id, order_value, is_qcom, qcom_orders_before, qcom_orders_lifetime, first_qcom_ts, DATEDIFF(\'day\', first_qcom_ts, order_ts) AS days_since_first_qcom, IFF(is_qcom, qcom_orders_lifetime, NULL) AS qcom_order_number_for_user, IFF(orders_before = 0, TRUE, FALSE) AS is_first_order, orders_before AS order_number_lifetime, orders_12m_before AS order_number_12m, IFF(online_orders_before > 0, TRUE, FALSE) AS had_online_before, IFF(offline_orders_before > 0, TRUE, FALSE) AS had_offline_before, CASE WHEN orders_before = 0 THEN \'New\' WHEN offline_orders_before > 0 AND online_orders_before = 0 AND channel = \'Online\' THEN \'Offline → Online\' WHEN online_orders_before > 0 AND offline_orders_before = 0 AND channel = \'Offline\' THEN \'Online → Offline\' WHEN online_orders_before > 0 AND offline_orders_before > 0 THEN \'Both\' WHEN channel = \'Online\' THEN \'Online-only\' ELSE \'Offline-only\' END AS channel_state, snitchx_enrolled_at IS NOT NULL AS is_snitchx_member, IFF(order_ts >= snitchx_enrolled_at, TRUE, FALSE) AS is_post_snitchx, snitchx_orders_before AS orders_post_snitchx_so_far, days_since_last_order, orders_last_30d, orders_last_90d, is_first_online_order, is_first_qcom_order FROM order_state WHERE channel = \'Online\' ); CREATE OR REPLACE TABLE qcom_customer_metrics AS ( WITH o AS ( SELECT phone, shopify_user_id, order_id, order_ts, order_value, channel, store_code, is_qcom, channel_state, is_snitchx_member, is_post_snitchx FROM qcom_orders_customer_state ), o_gaps AS ( SELECT o.*, MIN(CASE WHEN is_qcom THEN order_ts END) OVER (PARTITION BY phone) AS first_qcom_ts, MIN(CASE WHEN order_ts >= \'2025-10-01\' THEN order_ts END) OVER (PARTITION BY phone) AS first_order_sept, FROM o ), final as ( SELECT phone, MAX(shopify_user_id) AS shopify_user_id, MIN(order_ts) AS first_order_ts, MAX(order_ts) AS last_order_ts, DATEDIFF(\'day\', MAX(order_ts), CURRENT_TIMESTAMP()) AS days_since_last_order_overall, COUNT(DISTINCT order_id) AS total_orders, SUM(order_value) AS total_gmv, AVG(order_value) AS overall_aov, SUM(IFF(channel = \'Online\', 1, 0)) AS online_orders, SUM(IFF(channel = \'Offline\', 1, 0)) AS offline_orders, SUM(IFF(channel = \'Online\', order_value, 0)) AS online_gmv, SUM(IFF(channel = \'Offline\', order_value, 0)) AS offline_gmv, MAX(IFF(is_qcom, 1, 0)) AS is_qcom_user, MIN(first_qcom_ts) AS first_qcom_ts, DATEDIFF(\'day\', MIN(first_qcom_ts), CURRENT_TIMESTAMP()) AS days_since_first_qcom, SUM(IFF(is_qcom, 1, 0)) AS qcom_orders_total, SUM(IFF(is_qcom, order_value, 0)) AS qcom_gmv, AVG(IFF(is_qcom, order_value, NULL)) AS qcom_aov, SUM(IFF(NOT is_qcom, 1, 0)) AS non_qcom_orders_total, SUM(IFF(NOT is_qcom, order_value, 0)) AS non_qcom_gmv, AVG(IFF(NOT is_qcom, order_value, NULL)) AS non_qcom_aov, (SUM(IFF(is_qcom, 1, 0)) * 1.0) / NULLIF(COUNT(DISTINCT order_id), 0) AS qcom_order_share, (SUM(IFF(is_qcom, order_value, 0)) * 1.0) / NULLIF(SUM(order_value), 0) AS qcom_gmv_share, DATEDIFF(\'day\', MIN(order_ts), MIN(first_qcom_ts)) AS days_pre_qcom, DATEDIFF(\'day\', MIN(first_qcom_ts), CURRENT_TIMESTAMP()) AS days_post_qcom_to_today, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts, 1, 0)) AS pre_qcom_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts, order_value, 0)) AS pre_qcom_gmv, AVG(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts, order_value, NULL)) AS pre_qcom_aov, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts, 1, 0)) AS post_qcom_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts, order_value, 0)) AS post_qcom_gmv, SUM(IFF(order_ts >= \'2025-10-01\', order_value, 0)) AS post_launch_gmv, SUM(IFF(order_ts >= \'2025-10-01\', 1, 0)) AS post_launch_orders, AVG(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts, order_value, NULL)) AS post_qcom_aov, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts AND channel = \'Online\', 1, 0)) AS pre_online_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts AND channel = \'Offline\', 1, 0)) AS pre_offline_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts AND channel = \'Online\', 1, 0)) AS post_online_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts AND channel = \'Offline\', 1, 0)) AS post_offline_orders, MIN(first_order_sept) AS first_order_sept, DATEDIFF(\'day\', MIN(first_order_sept), CURRENT_TIMESTAMP()) AS days_since_first_order_sept, SUM(IFF(order_ts >= first_order_sept, 1, 0)) AS post_sept_orders, (SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts < first_qcom_ts, 1, 0)) * 30.0) / NULLIF(DATEDIFF(\'day\', MIN(order_ts), MIN(first_qcom_ts)), 0) AS pre_orders_per_30d, (SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= first_qcom_ts, 1, 0)) * 30.0) / NULLIF(DATEDIFF(\'day\', MIN(first_qcom_ts), CURRENT_TIMESTAMP()), 0) AS post_orders_per_30d, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= DATEADD(\'day\', -90, first_qcom_ts) AND order_ts < first_qcom_ts, 1, 0)) AS pre90_orders, SUM(IFF(first_qcom_ts IS NOT NULL AND order_ts >= DATEADD(\'day\', -90, first_qcom_ts) AND order_ts < first_qcom_ts, order_value, 0)) AS pre90_gmv, AVG(IFF(first_qcom_ts IS NOT NULL AND order_ts >= DATEADD(\'day\', -90, first_qcom_ts) AND order_ts < first_qcom_ts, order_value, NULL)) AS pre90_aov, MIN_BY(channel_state, order_ts) AS channel_state_at_first_order, MAX(IFF(channel_state = \'Offline → Online\', 1, 0)) AS ever_offline_to_online, MAX(IFF(is_snitchx_member, 1, 0)) AS is_snitchx_member_anytime, SUM(IFF(is_post_snitchx, 1, 0)) AS orders_post_snitchx, SUM(IFF(is_post_snitchx, order_value, 0)) AS gmv_post_snitchx, CASE WHEN SUM(IFF(is_qcom, 1, 0)) = 0 THEN \'0\' WHEN SUM(IFF(is_qcom, 1, 0)) = 1 THEN \'1\' WHEN SUM(IFF(is_qcom, 1, 0)) = 2 THEN \'2\' WHEN SUM(IFF(is_qcom, 1, 0)) = 3 THEN \'3\' ELSE \'4+\' END AS qcom_orders_bucket FROM o_gaps GROUP BY 1 ) SELECT * from final ); CREATE OR REPLACE TABLE qcom_pincodes_orders_metafield AS ( WITH qcom_pincodes AS ( SELECT DISTINCT TRY_TO_NUMBER(shipping_pincode) AS pincode FROM snitch_db.maplemonk.omni_order_processing_meta WHERE is_quick_com = TRUE AND TRY_TO_NUMBER(shipping_pincode) IS NOT NULL ), impact_users AS ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND TRY_TO_NUMBER(pincode) IN (SELECT pincode FROM qcom_pincodes) AND phone IS NOT NULL ), online_orders AS ( SELECT TO_CHAR(TO_NUMBER(REGEXP_REPLACE(f.order_name,\'[^0-9]\',\'\'))) AS order_id, RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone, TRIM(customer_id) AS shopify_user_id, \'Online\' AS channel, order_timestamp AS order_ts, gross_sales::NUMBER AS order_value, f.pincode, f.sku, f.sku_group, IFF(op.channel_order_number IS NOT NULL AND is_quick_com = true, 1,0) as is_qcom FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH f LEFT JOIN snitch_db.maplemonk.omni_order_processing_meta op ON f.line_item_id = op.channel_order_line_item_id WHERE gross_sales > 0 AND LOWER(f.order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' ), metafields as ( select sku_group as sku_group_m, category, material, designs, fit, sleeve_type, collar, color from snitch_db.maplemonk.metafields_data ), final as ( SELECT * FROM online_orders o left join metafields m on o.sku_group = m.sku_group_m WHERE o.phone IN (SELECT DISTINCT phone from impact_users) ) SELECT * FROM final ); CREATE OR REPLACE TABLE omni_inventory_cut_size AS ( WITH base AS ( SELECT m.*, UPPER(COALESCE(REGEXP_SUBSTR(m.sku, \'[^-]+$\'), m.size)) AS size_tok, DATE_TRUNC(\'hour\', m.inventory_logs) AS snap_hour FROM omni_inventory_meta_hourly m WHERE m.inventory_logs::time BETWEEN \'09:00\' AND \'12:00\' AND (m.location ILIKE \'BOHQ%\' OR m.location ILIKE \'BOH1Q%\') ), norm AS ( SELECT b.*, CASE WHEN size_tok IN (\'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\') THEN size_tok WHEN REGEXP_LIKE(size_tok, \'^\d{2}$\') THEN size_tok WHEN REGEXP_LIKE(size_tok, \'^\d{2}[A-Z]+$\') THEN REGEXP_SUBSTR(size_tok, \'^\d{2}\') ELSE size_tok END AS size_norm FROM base b ), with_flags AS ( SELECT n.*, SUM(IFF(n.inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS in_stock_count, MAX(IFF(size_norm = \'S\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_s, MAX(IFF(size_norm = \'M\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_m, MAX(IFF(size_norm = \'L\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_l, MAX(IFF(size_norm = \'XL\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_xl, MAX(IFF(size_norm = \'30\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_30, MAX(IFF(size_norm = \'32\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_32, MAX(IFF(size_norm = \'34\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_34, MAX(IFF(size_norm = \'36\' AND inventory_atp > 0, 1, 0)) OVER (PARTITION BY snap_hour, branch_code, store_name, sku_group) AS has_36 FROM norm n ), final AS ( SELECT snap_hour, branch_code, store_name, branch_name, sku_group, shopify_product_id, category_code, inventory_logs, location, SUM(inventory_atp) AS total_inventory, MAX(in_stock_count) AS in_stock_count, MAX(has_s) AS has_s, MAX(has_m) AS has_m, MAX(has_l) AS has_l, MAX(has_xl) AS has_xl, MAX(has_30) AS has_30, MAX(has_32) AS has_32, MAX(has_34) AS has_34, MAX(has_36) AS has_36, CASE WHEN MAX(in_stock_count) = 0 THEN \'out of stock\' WHEN (MAX(has_s) + MAX(has_m) + MAX(has_l) + MAX(has_xl)) = 4 OR (MAX(has_30) + MAX(has_32) + MAX(has_34) + MAX(has_36)) = 4 THEN \'full size\' ELSE \'cut size\' END AS cut_size_flag FROM with_flags GROUP BY snap_hour, branch_code, store_name, branch_name, sku_group, shopify_product_id, category_code, inventory_logs, location ) SELECT f.*, ROUND(COALESCE(( SELECT SUM(COALESCE(o.quantity, 1)) FROM omni_order_processing_meta o WHERE o.branch_code = f.branch_code AND o.channel_product_id = f.shopify_product_id AND o.location = f.location AND o.manifested_at IS NOT NULL AND o.order_status <> \'CANCELLED\' AND CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', o.created_at) >= CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', f.snap_hour) - INTERVAL \'24 HOURS\' AND CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', o.created_at) < CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', f.snap_hour) ), 0), 0) AS qty_sold_last_24h FROM final f ORDER BY f.snap_hour DESC, f.store_name, f.sku_group );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            